    # ----- Sub-component access. -----
    def ch_size(self):
        return 4
    def ch_at(self, i):
        return self.ch[i]

    async def configure_interrupt_routing(self, bank, channel_mask):
        """Route a set of channels to one of the two aggregate interrupt outputs.

        *§3.2 group 2, configuration.* Completes when INT_MSK_A/B has been
        updated; waits for nothing.

        The two banks are independent aggregate outputs, and a channel may be
        routed to both. ``channel_mask`` stays a bit vector rather than becoming
        a channel list because it genuinely is one: bit N routes channel N.

        **A hard prerequisite for every end-to-end operation, enforced by
        deadlock** on the event-wait profile. Completion IS the interrupt, so a
        test that routes nothing raises no interrupt, nothing calls
        ``notify_irq()``, and the first wait blocks forever. Routing at least one
        channel in a bank keeps the whole test alive, because ``notify_irq()``
        posts to every channel blind. That is intended: a hang is a more honest
        result than a green test whose completion path was never exercised.

        :param bank:         which aggregate output to program
        :param channel_mask: bit N routes channel N
        """
        vec = wb_dma_intmsk_s()
        vec.ch = channel_mask
        _subject = bank
        if _subject == 0:
            await self.regs_int_msk_a_write(vec)
        elif _subject == 1:
            await self.regs_int_msk_b_write(vec)
        else:
            raise ValueError('configure_interrupt_routing: unmatched match subject' + " (%r)" % (_subject,))

    async def notify_irq(self):
        for i in range(4):
            self.ch[i].wake.try_put(1)

    async def pause_engine(self, pause):
        """Pause or un-pause the whole engine, and wait until it has taken effect.

        *§3.2 group 2, configuration.* Global, not per-channel.

        Completes when a readback of ``CSR.PAUSE`` matches the requested value.
        The engine only pauses after the CURRENT transfer completes, so the write
        and the state change are NOT simultaneous -- which is the entire reason
        this is an operation rather than a register write, and the clearest small
        illustration of the blocking rule: the operation is not done when the
        store retires.

        It waits for that readback, and is the one wait in this model with no
        interrupt behind it -- in a real driver, a retry or timer loop rather than
        an ISR wake. The global CSR is not read-to-clear, so unlike the channel
        CSR this poll is genuinely side-effect-free and may run any number of
        times.

        :param pause: 1 to pause, 0 to resume
        """
        gcsr = wb_dma_gcsr_s()
        gcsr.pause = pause
        await self.regs_csr_write(gcsr)
        while True:
            gcsr = await self.regs_csr_read()
            if gcsr.pause == pause:
                break
            await self._imports.yield_()

    async def read_descriptor_residual(self, desc_ptr):
        """Read back how much of a descriptor's transfer actually moved.

        *§3.2 group 3, configuration.* Completes when DESC_CSR has been loaded
        back from memory and decoded; waits for nothing.

        A device-specific decode, not a memory service -- the same rationale that
        keeps ``write_descriptor()`` in this model. Only meaningful when SZ_WB is
        set in the channel CSR and the descriptor was cut short by
        ``skip_to_next_descriptor()``. This is how software learns how much of a
        variable-length payload actually moved, which is the whole point of §3.9.

        .. note::
           Open question (§6.1): §3.9 says the remaining BYTES are written back,
           into a field Table 1 defines as a 12-bit WORD count. One of the two is
           wrong. This returns the raw field and lets the caller decide.

        :param desc_ptr: the descriptor whose control word is read back
        """
        desc_csr = 0
        desc_csr = await self._imports.read32(desc_ptr)
        return (desc_csr & 0xfff)

    async def write_descriptor(self, at, prev, desc):
        """Write one external descriptor into memory and link it to its predecessor.

        *§3.2 group 3, configuration.* Completes when the descriptor is in memory
        at ``at``, terminated (DESC_NEXT zero), and ``prev`` -- if there is one --
        points at it. Waits for nothing. Returns a handle to the slot immediately
        after ``at``, i.e. the natural place for the next descriptor, so a caller
        can build a list in place one link at a time.

        This is DEVICE KNOWLEDGE written through a memory path, not a path to
        memory: the next-pointer linkage and the EOL rule are the operation, the
        layout is declared by :pss:struct:`wb_dma_desc_s`, and ``write32`` is
        merely how it lands. That is what makes it an operation where a generic
        ``write_buffer()`` would not be.

        ``at`` must be reachable from interface 0: descriptors are fetched from
        IF0 regardless of which interface the DATA moves on (§3.3).

        :param at:   where this descriptor goes
        :param prev: the descriptor to link from; null/zero means "head of list"
        :param desc: the descriptor contents; the caller's copy is not modified
        """
        d = wb_dma_desc_s()
        csr_word = 0
        # Deep copy: `desc` is the caller's struct (aggregates pass by handle)
        # and we terminate this link ourselves.
        d._pss_assign(desc)
        d.next = 0
        # This block is one call -- write_struct(at, d) -- once read_struct /
        # write_struct land; they are commented out of the front end's
        # addr_reg_pkg ("TODO: generic type"). wb_dma_desc_s already declares
        # the packed layout, so nothing here adds information.
        csr_word = d.csr.tot_sz
        csr_word |= d.csr.dst_sel << 16
        csr_word |= d.csr.src_sel << 17
        csr_word |= d.csr.inc_dst << 18
        csr_word |= d.csr.inc_src << 19
        csr_word |= d.csr.eol << 20
        await self._imports.write32(at, csr_word)
        await self._imports.write32((at + 4), d.adr0)
        await self._imports.write32((at + 8), d.adr1)
        await self._imports.write32((at + 12), d.next)
        # Extend the list. The check is on the resolved address rather than a
        # handle comparison, because an address handle is opaque and not
        # usefully comparable.
        if prev != 0:
            await self._imports.write32((prev + 12), (at & 0xffffffff))
        return (at + 16)
